  'Базовая прогрессия · 1→2': { de: 'Basisprogression · 1→2', es: 'Progresión básica · 1→2', fr: 'Progression de base · 1→2', it: 'Progressione base · 1→2', pt: 'Progressão básica · 1→2', ar: 'التدرج الأساسي · 1→2', hi: 'मूल प्रगति · 1→2', ja: '基本の進み方 · 1→2', ko: '기본 단계 · 1→2', zh: '基础进阶 · 1→2' },
  'Без громкости и давления в горле.': { de: 'Ohne Lautstärke und ohne Druck im Hals.', es: 'Sin volumen ni presión en la garganta.', fr: 'Sans volume ni pression dans la gorge.', it: 'Senza volume né pressione in gola.', pt: 'Sem volume nem pressão na garganta.', ar: 'دون رفع الصوت ودون ضغط في الحلق.', hi: 'आवाज़ ऊँची किए बिना और गले पर दबाव डाले बिना।', ja: '大きな声を出さず、のどに力を入れずに。', ko: '소리를 크게 내지 않고 목에 힘을 주지 않습니다.', zh: '不放大音量，不给喉咙施压。' },
