  'Вдох': { de: 'Einatmen', es: 'Inhalación', fr: 'Inspiration', it: 'Inspirazione', pt: 'Inspiração', ar: 'شهيق', hi: 'साँस लेना', ja: '吸う', ko: '들숨', zh: '吸气' },
