  'Ладони': { de: 'Handflächen', es: 'Palmas', fr: 'Paumes', it: 'Palmi', pt: 'Palmas', ar: 'الكفان', hi: 'हथेलियाँ', ja: '手のひら', ko: '손바닥', zh: '手掌' },
