  'Лотос · комфортный вариант': { de: 'Lotus · bequeme Variante', es: 'Loto · variante cómoda', fr: 'Lotus · variante confortable', it: 'Loto · variante comoda', pt: 'Lótus · variação confortável', ar: 'اللوتس · نسخة مريحة', hi: 'पद्मासन · आरामदायक रूप', ja: '蓮座 · 楽な形', ko: '연꽃 자세 · 편한 방식', zh: '莲花坐 · 舒适版' },
